import AVFoundation
import AppKit
import CoreAudio

@Observable
final class AudioMonitor {
  private(set) var isRecording = false
  private(set) var currentAppName: String?
  private(set) var recordingStartTime: Date?
  private(set) var permissionNeeded = false
  private(set) var micPermissionNeeded = false
  private(set) var isManualRecording = false
  private(set) var errorMessage: String?
  private(set) var graceCountdown: TimeInterval?
  private(set) var isSaving = false
  private(set) var formattedElapsed: String?
  private(set) var audioLevel: Float = 0
  private var savingCount = 0

  // Auto-recording triggered by call detection
  private var autoRecorder: (any RecorderSession)?
  private var autoRecordingAppName: String?
  private var autoRecordingBundleID: String?
  // Manual recording triggered by user
  private var manualRecorder: (any RecorderSession)?

  private var settingsTask: Task<Void, Never>?
  private var elapsedTimer: Timer?
  private var graceTask: Task<Void, Never>?

  // Restart rate limiting: max 3 restarts within 30 seconds
  private var autoRestartCount = 0
  private var autoRestartWindowStart: Date?
  private var manualRestartCount = 0
  private var manualRestartWindowStart: Date?

  private var micPollingTask: Task<Void, Never>?
  private var lastKnownMicRunning = false
  private var consecutiveInactivePolls = 0
  private var continuityCooldownUntil: Date?
  @ObservationIgnored private let dependencies: AudioMonitorDependencies

  // Settings
  var autoRecord: Bool = true
  var gracePeriod: TimeInterval = 5
  var micEnabled: Bool = true
  var saveDirectory: URL = URL(fileURLWithPath: defaultSaveDirectoryPath)
  var notifyOnStart: Bool = true
  var notifyOnSaved: Bool = true
  var notifyOnError: Bool = true

  private var errorGeneration = 0

  init(dependencies: AudioMonitorDependencies = .live) {
    self.dependencies = dependencies
  }

  // MARK: - Monitoring Lifecycle

  func startMonitoring(skipPermissionRequests: Bool = false) {
    guard settingsTask == nil else {
      Log.info(Log.monitor, "monitor", "startMonitoring skipped: already running")
      return
    }
    Log.info(Log.monitor, "monitor", "startMonitoring called (skip=\(skipPermissionRequests))")
    loadSettings()
    Log.info(
      Log.monitor, "monitor",
      "settings loaded: autoRecord=\(autoRecord), gracePeriod=\(gracePeriod), micEnabled=\(micEnabled)"
    )

    // CATap has no preflight API - permission is checked on first AudioHardwareCreateProcessTap call.
    // permissionNeeded will be set to true if recording fails with .permissionDenied.

    if !skipPermissionRequests {
      Task { @MainActor [weak self] in
        guard let self else { return }
        await self.dependencies.requestMicrophoneAccessIfNeeded()
      }
    }

    // Start call detection polling
    setupCallDetection()

    // Periodically reload settings
    settingsTask = Task { [weak self] in
      while !Task.isCancelled {
        guard let self else { return }
        await self.dependencies.sleep(.seconds(5))
        self.loadSettings()
      }
    }
  }

  func stopMonitoring() async {
    settingsTask?.cancel()
    settingsTask = nil
    micPollingTask?.cancel()
    micPollingTask = nil
    stopElapsedTimer()
    cancelGracePeriod()

    if let recorder = autoRecorder {
      _ = await recorder.stop()
      autoRecorder = nil
    }

    if let recorder = manualRecorder {
      _ = await recorder.stop()
      manualRecorder = nil
      isManualRecording = false
    }

    isRecording = false
    currentAppName = nil
    recordingStartTime = nil
  }

  // MARK: - Error

  func clearError() { errorMessage = nil }

  func setError(_ message: String) {
    Log.error(Log.monitor, "monitor", message)
    errorMessage = message
    notifyError(message: message)
    errorGeneration += 1
    let gen = errorGeneration
    Task { @MainActor [weak self] in
      guard let self else { return }
      await self.dependencies.sleep(.seconds(10))
      if self.errorGeneration == gen { self.errorMessage = nil }
    }
  }

  private func handleLowDiskSpace(_ remainingBytes: Int64) {
    let mb = remainingBytes / 1_000_000
    setError("Low disk space (\(mb) MB remaining)")
  }

  // MARK: - Elapsed Timer

  private func startElapsedTimer() {
    guard elapsedTimer == nil else { return }
    tickElapsed()
    elapsedTimer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
      Task { @MainActor [weak self] in
        self?.tickElapsed()
      }
    }
  }

  private func stopElapsedTimer() {
    elapsedTimer?.invalidate()
    elapsedTimer = nil
    formattedElapsed = nil
  }

  private func tickElapsed() {
    guard let start = recordingStartTime else {
      formattedElapsed = nil
      return
    }
    let total = max(0, Int(dependencies.now().timeIntervalSince(start)))
    let h = total / 3600
    let m = (total % 3600) / 60
    let s = total % 60
    formattedElapsed =
      h > 0
      ? String(format: "%d:%02d:%02d", h, m, s)
      : String(format: "%d:%02d", m, s)
  }

  // MARK: - Manual Recording

  func startManualRecording(resetRestartBudget: Bool = true) {
    guard manualRecorder == nil else {
      Log.info(Log.monitor, "monitor", "startManualRecording skipped: already recording")
      return
    }

    if resetRestartBudget {
      manualRestartCount = 0
      manualRestartWindowStart = nil
    }

    let useMic = micEnabled
    let recorder = dependencies.recorderFactory.makeRecorder(
      configuration: RecorderSessionConfiguration(
        bundleID: nil,
        appName: "Manual recording",
        micEnabled: useMic,
        saveDirectory: saveDirectory
      ),
      onFailure: { [weak self] failure in
        Task { @MainActor [weak self] in
          self?.handleManualRecorderFailure(failure)
        }
      },
      onAudioLevel: { [weak self] level in
        Task { @MainActor [weak self] in
          self?.audioLevel = level
        }
      },
      onLowDiskSpace: { [weak self] remaining in
        Task { @MainActor [weak self] in
          self?.handleLowDiskSpace(remaining)
        }
      },
      onContinuityEvent: { [weak self] event in
        Task { @MainActor [weak self] in
          self?.handleRecorderContinuityEvent(event)
        }
      })

    manualRecorder = recorder
    isManualRecording = true

    Task { @MainActor [weak self] in
      guard let self else { return }
      do {
        try await recorder.start()
        self.dependencies.saveAudioRecordingGranted()
        self.permissionNeeded = false
        self.recordingStartTime = self.dependencies.now()
        self.currentAppName = "Manual recording"
        self.isRecording = true
        self.startElapsedTimer()
        self.notifyRecordingStarted(appName: "Manual recording")
      } catch {
        self.setError("Failed to start recording: \(error.localizedDescription)")
        self.manualRecorder = nil
        self.isManualRecording = false
        self.updateAutoState()
      }
    }
  }

  private func handleManualRecorderFailure(_ failure: RecorderFailure) {
    guard let failedRecorder = manualRecorder else {
      Log.info(Log.monitor, "monitor", "handleManualRecorderFailure skipped: recorder already nil")
      return
    }
    manualRecorder = nil
    isManualRecording = false
    stopElapsedTimer()

    savingCount += 1
    isSaving = true
    Task {
      _ = await failedRecorder.stop()
      savingCount -= 1
      isSaving = savingCount > 0
    }

    switch failure {
    case .permissionDenied:
      permissionNeeded = true
      notifyPermissionLost()
      updateAutoState()
    case .lowDiskSpace:
      setError("Recording stopped - not enough disk space")
      updateAutoState()
    case .systemStopped, .other:
      if shouldAllowRestart(
        count: &manualRestartCount, windowStart: &manualRestartWindowStart)
      {
        setError("Recording interrupted - restarting...")
        startManualRecording(resetRestartBudget: false)
      } else {
        setError("Recording failed repeatedly")
      }
    }
  }

  func forceStopAutoRecording() {
    cancelGracePeriod()
    stopAutoRecording()
  }

  func stopManualRecording() {
    guard let recorder = manualRecorder else { return }
    let appName = currentAppName ?? recorder.appName
    manualRecorder = nil
    isManualRecording = false
    stopElapsedTimer()
    savingCount += 1
    isSaving = true
    Task {
      let url = await recorder.stop()
      savingCount -= 1
      isSaving = savingCount > 0
      if url != nil {
        notifyRecordingSaved(appName: appName)
      }
      updateAutoState()
      // Force re-evaluation so auto-recording starts if a call is still active
      lastKnownMicRunning = false
      evaluateCallState()
    }
  }

  // MARK: - Call Detection (macOS 14.2+)

  private func setupCallDetection() {
    let callers = dependencies.findActiveCallingProcesses()
    lastKnownMicRunning = !callers.isEmpty
    Log.info(
      Log.monitor, "monitor",
      "call detection started: polling every 3s, activeCallers=\(callers.count)"
    )

    // Check current state in case app starts mid-call
    if let first = callers.first {
      handleMicBecameActive(appBundleID: first)
    }

    // Poll every 3 seconds for active calling processes
    micPollingTask = Task { [weak self] in
      while !Task.isCancelled {
        guard let self else { return }
        await self.dependencies.sleep(.seconds(3))
        self.evaluateCallState()
      }
    }
  }

  // MARK: - Call State Evaluation

  /// Re-evaluate call state by checking which external processes have active calls.
  /// Called from polling loop every 3 seconds.
  private func evaluateCallState() {
    let callers = dependencies.findActiveCallingProcesses()
    let running = !callers.isEmpty

    if running {
      consecutiveInactivePolls = 0
      continuityCooldownUntil = nil
      if running != lastKnownMicRunning {
        Log.info(
          Log.monitor, "monitor",
          "call state changed: activeCallers=\(callers.count), running=\(running)")
        lastKnownMicRunning = true
        let bundleID = callers.count == 1 ? callers.first ?? nil : nil
        handleMicBecameActive(appBundleID: bundleID)
      } else if autoRecord, autoRecorder == nil, !isRecording, !isManualRecording {
        Log.info(Log.monitor, "monitor", "retrying auto-recording for active call")
        handleMicBecameActive(appBundleID: callers.first ?? nil)
      }
      return
    }

    if running != lastKnownMicRunning {
      Log.info(
        Log.monitor, "monitor",
        "call state changed: activeCallers=\(callers.count), running=\(running)")
      lastKnownMicRunning = running
    }

    guard autoRecorder != nil else { return }

    if shouldSuppressInactiveStop() {
      Log.info(Log.monitor, "monitor", "inactive poll ignored during continuity cooldown")
      return
    }

    consecutiveInactivePolls += 1
    guard consecutiveInactivePolls >= 2 else {
      Log.info(Log.monitor, "monitor", "inactive poll threshold not reached yet")
      return
    }

    handleMicBecameInactive()
  }

  /// Resolve helper subprocess bundle IDs to the parent app.
  /// e.g. "com.google.Chrome.helper.renderer" → "com.google.Chrome"
  private static func resolveParentBundleID(_ bundleID: String) -> String {
    let parts = bundleID.split(separator: ".")
    if let idx = parts.firstIndex(where: { $0 == "helper" }), idx > 1 {
      return parts[..<idx].joined(separator: ".")
    }
    return bundleID
  }

  /// Resolve a bundle ID to a human-readable app name.
  private static func resolveAppName(bundleID: String?) -> String {
    guard let bundleID else { return "Call" }
    let resolved = resolveParentBundleID(bundleID)
    if let app = NSRunningApplication.runningApplications(withBundleIdentifier: resolved).first,
      let name = app.localizedName
    {
      return name
    }
    // Fallback: try original bundle ID if parent resolution found nothing
    if resolved != bundleID,
      let app = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first,
      let name = app.localizedName
    {
      return name
    }
    // Last resort: extract last component of bundle ID (e.g. "com.zoom.us" -> "zoom")
    let components = bundleID.split(separator: ".")
    if let last = components.last, last != "app" {
      return String(last)
    }
    return "Call"
  }

  // MARK: - Auto Recording

  private func handleMicBecameActive(appBundleID: String? = nil) {
    cancelGracePeriod()
    consecutiveInactivePolls = 0

    guard autoRecord, !isRecording, !isManualRecording else {
      Log.info(
        Log.monitor, "monitor",
        "handleMicBecameActive skipped: autoRecord=\(autoRecord), isRecording=\(isRecording), isManualRecording=\(isManualRecording)"
      )
      return
    }

    // CATap permission is checked when AudioRecorder.start() creates the process tap.
    // If denied, the failure callback sets permissionNeeded = true.

    autoRecordingBundleID = appBundleID.map { Self.resolveParentBundleID($0) }
    autoRecordingAppName = Self.resolveAppName(bundleID: appBundleID)
    loadSettings()
    startAutoRecording()
  }

  private func handleMicBecameInactive() {
    guard autoRecorder != nil else {
      Log.info(Log.monitor, "monitor", "handleMicBecameInactive skipped: no active auto-recording")
      return
    }
    Log.info(Log.monitor, "monitor", "mic inactive, starting grace period")
    startGracePeriod()
  }

  private func handleRecorderContinuityEvent(_ event: RecorderContinuityEvent) {
    let now = dependencies.now()
    continuityCooldownUntil = now.addingTimeInterval(max(gracePeriod, 8))
    consecutiveInactivePolls = 0
    cancelGracePeriod()
    Log.info(Log.monitor, "monitor", "continuity event observed: \(String(describing: event))")
  }

  private func shouldSuppressInactiveStop() -> Bool {
    guard let continuityCooldownUntil else { return false }
    if continuityCooldownUntil > dependencies.now() {
      return true
    }
    self.continuityCooldownUntil = nil
    return false
  }

  private func startAutoRecording(resetRestartBudget: Bool = true) {
    guard autoRecorder == nil else {
      Log.info(Log.monitor, "monitor", "startAutoRecording skipped: already recording")
      return
    }

    if resetRestartBudget {
      autoRestartCount = 0
      autoRestartWindowStart = nil
    }

    let useMic = micEnabled
    let appName = autoRecordingAppName ?? "Call"
    let recorder = dependencies.recorderFactory.makeRecorder(
      configuration: RecorderSessionConfiguration(
        bundleID: autoRecordingBundleID,
        appName: appName,
        micEnabled: useMic,
        saveDirectory: saveDirectory
      ),
      onFailure: { [weak self] failure in
        Task { @MainActor [weak self] in
          self?.handleAutoRecorderFailure(failure)
        }
      },
      onAudioLevel: { [weak self] level in
        Task { @MainActor [weak self] in
          self?.audioLevel = level
        }
      },
      onLowDiskSpace: { [weak self] remaining in
        Task { @MainActor [weak self] in
          self?.handleLowDiskSpace(remaining)
        }
      },
      onContinuityEvent: { [weak self] event in
        Task { @MainActor [weak self] in
          self?.handleRecorderContinuityEvent(event)
        }
      })

    autoRecorder = recorder
    Log.info(
      Log.monitor, "monitor", "starting auto-recording (call detected, app=\(appName))")

    Task { @MainActor [weak self] in
      guard let self else { return }
      do {
        try await recorder.start()
        self.dependencies.saveAudioRecordingGranted()
        self.permissionNeeded = false
        self.isRecording = true
        self.currentAppName = appName
        self.recordingStartTime = self.dependencies.now()
        self.startElapsedTimer()
        self.notifyRecordingStarted(appName: appName)
      } catch {
        self.setError("Failed to start recording: \(error.localizedDescription)")
        if let recError = error as? RecorderError,
          case .permissionDenied = recError
        {
          self.permissionNeeded = true
        }
        self.autoRecorder = nil
        self.updateAutoState()
      }
    }
  }

  private func stopAutoRecording() {
    guard let recorder = autoRecorder else { return }
    let appName = autoRecordingAppName ?? "Call"
    autoRecorder = nil
    autoRecordingAppName = nil
    autoRecordingBundleID = nil
    Log.info(Log.monitor, "monitor", "stopping auto-recording (app=\(appName))")
    savingCount += 1
    isSaving = true
    Task {
      let url = await recorder.stop()
      savingCount -= 1
      isSaving = savingCount > 0
      if url != nil {
        notifyRecordingSaved(appName: appName)
      }
      updateAutoState()
    }
  }

  private func handleAutoRecorderFailure(_ failure: RecorderFailure) {
    guard let failedRecorder = autoRecorder else {
      Log.info(Log.monitor, "monitor", "handleAutoRecorderFailure skipped: recorder already nil")
      return
    }
    autoRecorder = nil
    stopElapsedTimer()
    cancelGracePeriod()

    savingCount += 1
    isSaving = true
    Task {
      _ = await failedRecorder.stop()
      savingCount -= 1
      isSaving = savingCount > 0
    }

    switch failure {
    case .permissionDenied:
      permissionNeeded = true
      notifyPermissionLost()
      autoRecordingAppName = nil
      autoRecordingBundleID = nil
      updateAutoState()
    case .systemStopped:
      if shouldAllowRestart(
        count: &autoRestartCount, windowStart: &autoRestartWindowStart)
      {
        Log.info(Log.monitor, "monitor", "auto-recording interrupted, restarting")
        startAutoRecording(resetRestartBudget: false)
      } else {
        Log.error(Log.monitor, "monitor", "auto-recording restart limit exceeded")
        setError("Recording failed repeatedly")
        autoRecordingAppName = nil
        autoRecordingBundleID = nil
        updateAutoState()
      }
    case .lowDiskSpace:
      setError("Recording stopped - not enough disk space")
      autoRecordingAppName = nil
      autoRecordingBundleID = nil
      updateAutoState()
    case .other:
      setError("Recording interrupted")
      autoRecordingAppName = nil
      autoRecordingBundleID = nil
      updateAutoState()
    }
  }

  // MARK: - Grace Period

  private func startGracePeriod() {
    graceTask?.cancel()
    let period = gracePeriod
    graceTask = Task { @MainActor [weak self] in
      guard let self else { return }
      let start = self.dependencies.now()
      while !Task.isCancelled {
        let elapsed = self.dependencies.now().timeIntervalSince(start)
        let remaining = period - elapsed
        if remaining <= 0 {
          self.graceCountdown = nil
          self.stopAutoRecording()
          return
        }
        self.graceCountdown = remaining
        await self.dependencies.sleep(.seconds(1))
      }
    }
  }

  private func cancelGracePeriod() {
    graceTask?.cancel()
    graceTask = nil
    graceCountdown = nil
    consecutiveInactivePolls = 0
  }

  // MARK: - State

  private func updateAutoState() {
    guard !isManualRecording else { return }
    if autoRecorder != nil {
      isRecording = true
    } else {
      isRecording = false
      currentAppName = nil
      recordingStartTime = nil
      audioLevel = 0
      stopElapsedTimer()
    }
  }

  private func loadSettings() {
    let settings = dependencies.loadSettings()
    autoRecord = settings.autoRecord
    gracePeriod = settings.gracePeriod
    micEnabled = settings.micEnabled
    saveDirectory = settings.saveDirectory
    notifyOnStart = settings.notifyOnStart
    notifyOnSaved = settings.notifyOnSaved
    notifyOnError = settings.notifyOnError
    micPermissionNeeded =
      micEnabled && dependencies.microphoneAuthorizationStatus() != .authorized
  }

  // MARK: - Restart Rate Limiting

  private func shouldAllowRestart(
    count: inout Int, windowStart: inout Date?, max: Int = 3, window: TimeInterval = 30
  ) -> Bool {
    let now = dependencies.now()
    if let start = windowStart, now.timeIntervalSince(start) > window {
      count = 0
      windowStart = nil
    }
    if windowStart == nil { windowStart = now }
    count += 1
    return count <= max
  }

  // MARK: - Notifications

  private func notifyRecordingStarted(appName: String) {
    guard notifyOnStart else { return }
    dependencies.hud.showRecordingStarted(appName: appName)
  }

  private func notifyRecordingSaved(appName: String) {
    guard notifyOnSaved else { return }
    dependencies.hud.showRecordingSaved(appName: appName)
  }

  private func notifyError(message: String) {
    guard notifyOnError else { return }
    dependencies.hud.showError(message: message)
  }

  /// Send system notification when audio recording permission is revoked.
  /// Used because the user may be focused on their call app and not see the menu bar.
  private func notifyPermissionLost() {
    Task { @MainActor [weak self] in
      guard let self else { return }
      await self.dependencies.notifyPermissionLost()
    }
  }
}

extension Double {
  func clamped(to range: ClosedRange<Double>, default defaultValue: Double) -> Double {
    self == 0 ? defaultValue : min(max(self, range.lowerBound), range.upperBound)
  }
}

@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreMedia
import Testing

@testable import myproject-d

@Suite("PCM-to-CMSampleBuffer Conversion")
struct PCMConversionTests {

  /// Create a synthetic AVAudioPCMBuffer with known sample data.
  private func makePCMBuffer(
    sampleRate: Double = 48000, channels: UInt32 = 2, frameCount: UInt32 = 1024
  ) -> AVAudioPCMBuffer? {
    guard
      let format = AVAudioFormat(
        standardFormatWithSampleRate: sampleRate, channels: channels)
    else { return nil }
    guard let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: frameCount)
    else { return nil }
    buffer.frameLength = frameCount

    // Fill with a simple sine wave so we can verify data survives conversion
    if let floatData = buffer.floatChannelData {
      for ch in 0..<Int(channels) {
        for i in 0..<Int(frameCount) {
          floatData[ch][i] = sin(Float(i) * 0.1)
        }
      }
    }
    return buffer
  }

  @Test("converts stereo 48kHz buffer successfully")
  func convertsStereo48kHz() {
    let pcm = makePCMBuffer(sampleRate: 48000, channels: 2, frameCount: 1024)!
    let result = pcm.asSampleBuffer()
    #expect(result != nil)
  }

  @Test("converts mono 44.1kHz buffer successfully")
  func convertsMono441kHz() {
    let pcm = makePCMBuffer(sampleRate: 44100, channels: 1, frameCount: 512)!
    let result = pcm.asSampleBuffer()
    #expect(result != nil)
  }

  @Test("preserves sample count")
  func preservesSampleCount() {
    let frameCount: UInt32 = 1024
    let pcm = makePCMBuffer(frameCount: frameCount)!
    let sb = pcm.asSampleBuffer()!
    #expect(CMSampleBufferGetNumSamples(sb) == Int(frameCount))
  }

  @Test("preserves sample rate in format description")
  func preservesSampleRate() {
    let pcm = makePCMBuffer(sampleRate: 48000)!
    let sb = pcm.asSampleBuffer()!
    let fmt = CMSampleBufferGetFormatDescription(sb)!
    let asbd = CMAudioFormatDescriptionGetStreamBasicDescription(fmt)!.pointee
    #expect(asbd.mSampleRate == 48000)
  }

  @Test("has valid presentation timestamp")
  func hasValidTimestamp() {
    let pcm = makePCMBuffer()!
    let sb = pcm.asSampleBuffer()!
    let pts = CMSampleBufferGetPresentationTimeStamp(sb)
    #expect(pts.isValid)
    #expect(pts.seconds > 0)
  }

  @Test("output contains audio data")
  func containsAudioData() {
    let pcm = makePCMBuffer(frameCount: 1024)!
    let sb = pcm.asSampleBuffer()!
    let blockBuffer = CMSampleBufferGetDataBuffer(sb)
    #expect(blockBuffer != nil)
    #expect(CMBlockBufferGetDataLength(blockBuffer!) > 0)
  }
}

// MARK: - AEC Processing Tests

@Suite("AEC Processing")
struct AECProcessingTests {
  /// Short dual-track recording (5.9s) with known-good reference processed file
  private static let testRecording = "2026-03-11-092853-2FD4"

  private static let pcmSettings: [String: Any] = [
    AVFormatIDKey: kAudioFormatLinearPCM,
    AVSampleRateKey: 16000.0,
    AVNumberOfChannelsKey: 1,
    AVLinearPCMBitDepthKey: 32,
    AVLinearPCMIsFloatKey: true,
    AVLinearPCMIsBigEndianKey: false,
    AVLinearPCMIsNonInterleaved: false,
  ]

  /// Copy audio.m4a to temp dir and run AEC processing.
  private func processInTemp(_ name: String) async throws -> (tmpDir: URL, output: URL) {
    let sourceDir = try TestFixtures.recordingDirectory(named: name)
    let audioURL = sourceDir.appending(path: "audio.m4a")
    try #require(
      FileManager.default.fileExists(atPath: audioURL.path(percentEncoded: false)),
      "Test recording not found: \(name)")

    let tmpDir = FileManager.default.temporaryDirectory
      .appending(path: "myproject-d-aec-test-\(UUID().uuidString)")
    try FileManager.default.createDirectory(at: tmpDir, withIntermediateDirectories: true)
    try FileManager.default.copyItem(
      at: audioURL, to: tmpDir.appending(path: "audio.m4a"))

    await AECProcessor.process(recordingDirectory: tmpDir)
    return (tmpDir, tmpDir.appending(path: "audio-processed.m4a"))
  }

  @Test("produces dual-track 16kHz mono output with matching duration")
  func outputFormat() async throws {
    let (tmpDir, outputURL) = try await processInTemp(Self.testRecording)
    defer { try? FileManager.default.removeItem(at: tmpDir) }

    try #require(
      FileManager.default.fileExists(atPath: outputURL.path(percentEncoded: false)),
      "Processed file was not created")

    let asset = AVURLAsset(url: outputURL)
    let tracks = try await asset.loadTracks(withMediaType: .audio)
    #expect(tracks.count == 2)

    for (i, track) in tracks.enumerated() {
      let descs = try await track.load(.formatDescriptions)
      try #require(!descs.isEmpty, "Track \(i): no format descriptions")
      let asbd = CMAudioFormatDescriptionGetStreamBasicDescription(descs[0])!.pointee
      #expect(asbd.mSampleRate == 16000, "Track \(i): expected 16kHz, got \(asbd.mSampleRate)")
      #expect(
        asbd.mChannelsPerFrame == 1, "Track \(i): expected mono, got \(asbd.mChannelsPerFrame)")
    }

    // Duration should be within 1s of original (AAC encoder padding)
    let inputDur = try await AVURLAsset(url: tmpDir.appending(path: "audio.m4a"))
      .load(.duration).seconds
    let outputDur = try await asset.load(.duration).seconds
    #expect(
      abs(outputDur - inputDur) < 1.0,
      "Duration mismatch: input=\(inputDur)s, output=\(outputDur)s")
  }

  @Test("output properties match reference processed file")
  func matchesReference() async throws {
    let refProcessedURL = try TestFixtures.recordingDirectory(named: Self.testRecording)
      .appending(path: "audio-processed.m4a")
    try #require(
      FileManager.default.fileExists(atPath: refProcessedURL.path(percentEncoded: false)),
      "Reference processed file not found")

    let (tmpDir, outputURL) = try await processInTemp(Self.testRecording)
    defer { try? FileManager.default.removeItem(at: tmpDir) }

    let refAsset = AVURLAsset(url: refProcessedURL)
    let outAsset = AVURLAsset(url: outputURL)

    // Duration within 0.5s
    let refDur = try await refAsset.load(.duration).seconds
    let outDur = try await outAsset.load(.duration).seconds
    #expect(abs(outDur - refDur) < 0.5, "Duration: ref=\(refDur)s, out=\(outDur)s")

    // File size within 20%
    let outSize =
      try FileManager.default.attributesOfItem(
        atPath: outputURL.path(percentEncoded: false))[.size] as! Int
    let refSize =
      try FileManager.default.attributesOfItem(
        atPath: refProcessedURL.path(percentEncoded: false))[.size] as! Int
    let ratio = Double(outSize) / Double(refSize)
    #expect(
      ratio > 0.8 && ratio < 1.2,
      "File size: ref=\(refSize), out=\(outSize), ratio=\(String(format: "%.2f", ratio))")
  }

  @Test("processed mic track contains non-silent audio")
  func micTrackNotSilent() async throws {
    let (tmpDir, outputURL) = try await processInTemp(Self.testRecording)
    defer { try? FileManager.default.removeItem(at: tmpDir) }

    let asset = AVURLAsset(url: outputURL)
    let tracks = try await asset.loadTracks(withMediaType: .audio)
    try #require(tracks.count >= 2, "Need at least 2 tracks")

    let reader = try AVAssetReader(asset: asset)
    let output = AVAssetReaderTrackOutput(
      track: tracks[1], outputSettings: Self.pcmSettings)
    reader.add(output)
    try #require(reader.startReading(), "Reader failed to start")

    var peakLevel: Float = 0
    var totalSamples = 0
    while let buffer = output.copyNextSampleBuffer() {
      guard let blockBuffer = CMSampleBufferGetDataBuffer(buffer) else { continue }
      let length = CMBlockBufferGetDataLength(blockBuffer)
      let floatCount = length / MemoryLayout<Float>.size
      totalSamples += floatCount

      var data = [Float](repeating: 0, count: floatCount)
      data.withUnsafeMutableBufferPointer { ptr in
        _ = CMBlockBufferCopyDataBytes(
          blockBuffer, atOffset: 0, dataLength: length,
          destination: ptr.baseAddress!)
      }
      for s in data {
        let abs = Swift.abs(s)
        if abs > peakLevel { peakLevel = abs }
      }
    }

    #expect(totalSamples > 0, "No samples read from mic track")
    #expect(peakLevel > 0.001, "Mic track appears silent (peak=\(peakLevel))")
  }

  @Test("per-second RMS of mic track matches reference within tolerance")
  func micRMSMatchesReference() async throws {
    let refProcessedURL = try TestFixtures.recordingDirectory(named: Self.testRecording)
      .appending(path: "audio-processed.m4a")
    try #require(
      FileManager.default.fileExists(atPath: refProcessedURL.path(percentEncoded: false)))

    let (tmpDir, outputURL) = try await processInTemp(Self.testRecording)
    defer { try? FileManager.default.removeItem(at: tmpDir) }

    let refSamples = try await readSamples(from: refProcessedURL, trackIndex: 1)
    let outSamples = try await readSamples(from: outputURL, trackIndex: 1)

    // Compare per-second RMS
    let sampleRate = 16000
    let seconds = min(refSamples.count, outSamples.count) / sampleRate
    try #require(seconds > 0, "Not enough samples for RMS comparison")

    for s in 0..<seconds {
      let range = s * sampleRate..<(s + 1) * sampleRate
      let refRMS = rms(Array(refSamples[range]))
      let outRMS = rms(Array(outSamples[range]))
      #expect(
        abs(refRMS - outRMS) < 0.05,
        "RMS mismatch at second \(s): ref=\(refRMS), out=\(outRMS)")
    }
  }

  // MARK: - Helpers

  private func readSamples(from url: URL, trackIndex: Int) async throws -> [Float] {
    let asset = AVURLAsset(url: url)
    let reader = try AVAssetReader(asset: asset)
    let tracks = try await asset.loadTracks(withMediaType: .audio)
    try #require(tracks.count > trackIndex, "Track \(trackIndex) not found")

    let output = AVAssetReaderTrackOutput(
      track: tracks[trackIndex], outputSettings: Self.pcmSettings)
    reader.add(output)
    try #require(reader.startReading())

    var samples: [Float] = []
    while let buffer = output.copyNextSampleBuffer() {
      guard let blockBuffer = CMSampleBufferGetDataBuffer(buffer) else { continue }
      let length = CMBlockBufferGetDataLength(blockBuffer)
      let floatCount = length / MemoryLayout<Float>.size
      let startIndex = samples.count
      samples.append(contentsOf: repeatElement(Float(0), count: floatCount))
      samples.withUnsafeMutableBufferPointer { ptr in
        _ = CMBlockBufferCopyDataBytes(
          blockBuffer, atOffset: 0, dataLength: length,
          destination: ptr.baseAddress!.advanced(by: startIndex))
      }
    }
    return samples
  }

  private func rms(_ samples: [Float]) -> Float {
    guard !samples.isEmpty else { return 0 }
    var sum: Float = 0
    for s in samples { sum += s * s }
    return (sum / Float(samples.count)).squareRoot()
  }
}

// MARK: - Gap Filling Tests

@Suite("Gap Filling")
struct GapFillingTests {

  /// Create a CMSampleBuffer with known PTS and sample count for testing.
  private func makeSampleBuffer(
    pts: CMTime, sampleCount: Int, sampleRate: Double = 48000, channels: Int = 1
  ) -> CMSampleBuffer? {
    AudioRecorder.makeSilentSampleBuffer(
      channelCount: channels,
      sampleCount: sampleCount,
      sampleRate: sampleRate,
      presentationTimeStamp: pts
    )
  }

  @Test("makeSilentSampleBuffer creates valid buffer with correct properties")
  func silentBufferProperties() {
    let pts = CMTime(value: 48000, timescale: 48000)  // 1.0s

    let sb = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 2, sampleCount: 1024,
      sampleRate: 48000, presentationTimeStamp: pts
    )
    #expect(sb != nil)
    let buffer = sb!

    #expect(CMSampleBufferGetNumSamples(buffer) == 1024)
    #expect(CMSampleBufferGetPresentationTimeStamp(buffer) == pts)
    #expect(CMSampleBufferDataIsReady(buffer))

    // Verify data is all zeros (silence)
    let blockBuffer = CMSampleBufferGetDataBuffer(buffer)!
    let length = CMBlockBufferGetDataLength(blockBuffer)
    #expect(length == 1024 * MemoryLayout<Float>.size * 2)

    var data = [UInt8](repeating: 1, count: length)
    data.withUnsafeMutableBufferPointer { ptr in
      _ = CMBlockBufferCopyDataBytes(
        blockBuffer, atOffset: 0, dataLength: length,
        destination: ptr.baseAddress!)
    }
    #expect(data.allSatisfy { $0 == 0 }, "Silent buffer should be all zeros")
  }

  @Test("makeSilentSampleBuffer works for mono and stereo")
  func silentBufferChannels() {
    let pts = CMTime(value: 0, timescale: 48000)

    let mono = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 1, sampleCount: 512,
      sampleRate: 48000, presentationTimeStamp: pts)
    let stereo = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 2, sampleCount: 512,
      sampleRate: 48000, presentationTimeStamp: pts)

    #expect(mono != nil)
    #expect(stereo != nil)

    let monoSize = CMBlockBufferGetDataLength(CMSampleBufferGetDataBuffer(mono!)!)
    let stereoSize = CMBlockBufferGetDataLength(CMSampleBufferGetDataBuffer(stereo!)!)
    #expect(monoSize == 512 * MemoryLayout<Float>.size * 1)
    #expect(stereoSize == 512 * MemoryLayout<Float>.size * 2)
  }

  @Test("bufferEndTime computes correct end time")
  func bufferEndTimeComputation() {
    let pts = CMTime(value: 48000, timescale: 48000)  // 1.0s
    let sb = makeSampleBuffer(pts: pts, sampleCount: 1024)!

    let end = AudioRecorder.bufferEndTime(sb)
    #expect(end.isValid)

    // End should be pts + 1024/48000 = 1.0 + 0.02133... ≈ 1.02133s
    let expected = 1.0 + 1024.0 / 48000.0
    #expect(abs(end.seconds - expected) < 0.0001)
  }

  @Test("bufferEndTime handles different sample counts")
  func bufferEndTimeVariousCounts() {
    let pts = CMTime(value: 0, timescale: 48000)

    for count in [256, 512, 1024, 2048] {
      let sb = makeSampleBuffer(pts: pts, sampleCount: count)!
      let end = AudioRecorder.bufferEndTime(sb)
      let expected = Double(count) / 48000.0
      #expect(
        abs(end.seconds - expected) < 0.0001,
        "count=\(count): expected \(expected), got \(end.seconds)")
    }
  }

  @Test("bufferEndTime returns invalid for nil format description")
  func bufferEndTimeInvalid() {
    // A buffer with no format description should return .invalid from fallback path
    // This is hard to construct, so just verify the normal path works
    let sb = makeSampleBuffer(
      pts: CMTime(value: 0, timescale: 48000), sampleCount: 1024)!
    let end = AudioRecorder.bufferEndTime(sb)
    #expect(end.isValid)
  }

  // MARK: - Silent Buffer Format Correctness

  @Test("silent buffer has clean LPCM ASBD with no extensions")
  func silentBufferCleanASBD() {
    let sb = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 2, sampleCount: 1024,
      sampleRate: 48000, presentationTimeStamp: CMTime(value: 0, timescale: 48000)
    )!
    let fd = CMSampleBufferGetFormatDescription(sb)!
    let asbd = CMAudioFormatDescriptionGetStreamBasicDescription(fd)!.pointee

    #expect(asbd.mFormatID == kAudioFormatLinearPCM)
    #expect(asbd.mSampleRate == 48000)
    #expect(asbd.mChannelsPerFrame == 2)
    #expect(asbd.mBitsPerChannel == 32)
    #expect(asbd.mBytesPerFrame == UInt32(MemoryLayout<Float>.size * 2))
    #expect(asbd.mBytesPerPacket == UInt32(MemoryLayout<Float>.size * 2))
    #expect(asbd.mFramesPerPacket == 1)
    #expect(asbd.mFormatFlags & kAudioFormatFlagIsFloat != 0)
    #expect(asbd.mFormatFlags & kAudioFormatFlagIsPacked != 0)
  }

  @Test("silent buffer mono ASBD matches mic pipeline format")
  func silentBufferMonoASBD() {
    let sb = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 1, sampleCount: 512,
      sampleRate: 48000, presentationTimeStamp: CMTime(value: 0, timescale: 48000)
    )!
    let fd = CMSampleBufferGetFormatDescription(sb)!
    let asbd = CMAudioFormatDescriptionGetStreamBasicDescription(fd)!.pointee

    #expect(asbd.mChannelsPerFrame == 1)
    #expect(asbd.mBytesPerFrame == UInt32(MemoryLayout<Float>.size))
    #expect(asbd.mBytesPerPacket == UInt32(MemoryLayout<Float>.size))
  }

  // MARK: - Silence Buffer Boundary Conditions

  @Test("makeSilentSampleBuffer handles minimum sample count")
  func silentBufferMinSamples() {
    let sb = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 1, sampleCount: 1,
      sampleRate: 48000, presentationTimeStamp: CMTime(value: 0, timescale: 48000)
    )
    #expect(sb != nil)
    #expect(CMSampleBufferGetNumSamples(sb!) == 1)
    let length = CMBlockBufferGetDataLength(CMSampleBufferGetDataBuffer(sb!)!)
    #expect(length == MemoryLayout<Float>.size)
  }

  @Test("makeSilentSampleBuffer handles large chunk (2048 samples)")
  func silentBufferLargeChunk() {
    let sb = AudioRecorder.makeSilentSampleBuffer(
      channelCount: 2, sampleCount: 2048,
      sampleRate: 48000, presentationTimeStamp: CMTime(value: 0, timescale: 48000)
    )
    #expect(sb != nil)
    #expect(CMSampleBufferGetNumSamples(sb!) == 2048)
  }

  @Test("makeSilentSampleBuffer preserves PTS across range of timestamps")
  func silentBufferPTSPreserved() {
    let timestamps: [CMTime] = [
      .zero,
      CMTime(value: 48000, timescale: 48000),  // 1s
      CMTime(value: 48000 * 3600, timescale: 48000),  // 1 hour
      CMTime(value: 48000 * 7200, timescale: 48000),  // 2 hours
    ]
    for pts in timestamps {
      let sb = AudioRecorder.makeSilentSampleBuffer(
        channelCount: 1, sampleCount: 1024,
        sampleRate: 48000, presentationTimeStamp: pts
      )!
      #expect(
        CMSampleBufferGetPresentationTimeStamp(sb) == pts,
        "PTS mismatch at \(pts.seconds)s")
    }
  }

  // MARK: - bufferEndTime Continuity

  @Test("consecutive buffers have continuous timeline")
  func bufferEndTimeContinuity() {
    // Simulate 5 consecutive 1024-sample buffers, verify no gaps in timeline
    var currentPts = CMTime(value: 0, timescale: 48000)
    for i in 0..<5 {
      let sb = makeSampleBuffer(pts: currentPts, sampleCount: 1024)!
      let endTime = AudioRecorder.bufferEndTime(sb)
      #expect(endTime.isValid, "Buffer \(i) endTime should be valid")

      let expectedEnd = CMTimeAdd(
        currentPts, CMTime(value: 1024, timescale: 48000))
      #expect(
        abs(endTime.seconds - expectedEnd.seconds) < 0.00001,
        "Buffer \(i): end \(endTime.seconds) != expected \(expectedEnd.seconds)")

      currentPts = endTime
    }
    // After 5 buffers of 1024 samples at 48kHz: 5*1024/48000 = 0.10667s
    #expect(abs(currentPts.seconds - 5.0 * 1024.0 / 48000.0) < 0.00001)
  }

  @Test("bufferEndTime at 2-hour mark has sub-sample precision")
  func bufferEndTimeLongRecording() {
    // Simulate buffer at 2h mark - verify no precision loss
    let twoHours = CMTime(value: Int64(48000 * 7200), timescale: 48000)
    let sb = makeSampleBuffer(pts: twoHours, sampleCount: 1024)!
    let end = AudioRecorder.bufferEndTime(sb)

    let expected = 7200.0 + 1024.0 / 48000.0
    #expect(
      abs(end.seconds - expected) < 0.00001,
      "Precision loss at 2h: expected \(expected), got \(end.seconds)")
  }

}

// MARK: - Resample + Downmix Tests

@Suite("System Audio Resample")
struct ResampleTests {

  /// Create an interleaved stereo buffer with known L/R values.
  private func makeStereoBuffer(
    sampleRate: Double, frameCount: Int, left: Float, right: Float
  ) -> AVAudioPCMBuffer {
    let fmt = AVAudioFormat(
      commonFormat: .pcmFormatFloat32, sampleRate: sampleRate, channels: 2, interleaved: true)!
    let buf = AVAudioPCMBuffer(pcmFormat: fmt, frameCapacity: AVAudioFrameCount(frameCount))!
    buf.frameLength = AVAudioFrameCount(frameCount)
    let data = buf.floatChannelData![0]
    for i in 0..<frameCount {
      data[i * 2] = left
      data[i * 2 + 1] = right
    }
    return buf
  }

  /// Create an interleaved mono buffer with a constant value.
  private func makeMonoBuffer(
    sampleRate: Double, frameCount: Int, value: Float
  ) -> AVAudioPCMBuffer {
    let fmt = AVAudioFormat(
      commonFormat: .pcmFormatFloat32, sampleRate: sampleRate, channels: 1, interleaved: true)!
    let buf = AVAudioPCMBuffer(pcmFormat: fmt, frameCapacity: AVAudioFrameCount(frameCount))!
    buf.frameLength = AVAudioFrameCount(frameCount)
    let data = buf.floatChannelData![0]
    for i in 0..<frameCount { data[i] = value }
    return buf
  }

  @Test("stereo 48kHz downmixes to mono without resampling")
  func stereoDownmixNoResample() {
    let input = makeStereoBuffer(sampleRate: 48000, frameCount: 1024, left: 0.6, right: 0.4)
    let result = AudioRecorder.resampleToMono48k(input, sourceRate: 48000)!

    #expect(result.format.sampleRate == 48000)
    #expect(result.format.channelCount == 1)
    #expect(Int(result.frameLength) == 1024)

    let out = result.floatChannelData![0]
    for i in 0..<1024 {
      #expect(abs(out[i] - 0.5) < 0.0001, "Frame \(i): expected 0.5, got \(out[i])")
    }
  }

  @Test("stereo 24kHz resamples and downmixes to mono 48kHz")
  func stereo24kResampleDownmix() {
    let input = makeStereoBuffer(sampleRate: 24000, frameCount: 240, left: 0.8, right: 0.2)
    let result = AudioRecorder.resampleToMono48k(input, sourceRate: 24000)!

    #expect(result.format.sampleRate == 48000)
    #expect(result.format.channelCount == 1)
    // 240 frames at 24kHz -> 480 frames at 48kHz
    #expect(Int(result.frameLength) == 480)

    let out = result.floatChannelData![0]
    for i in 0..<480 {
      #expect(abs(out[i] - 0.5) < 0.0001, "Frame \(i): expected 0.5, got \(out[i])")
    }
  }

  @Test("mono passthrough at 48kHz copies data unchanged")
  func monoPassthrough() {
    let input = makeMonoBuffer(sampleRate: 48000, frameCount: 512, value: 0.75)
    let result = AudioRecorder.resampleToMono48k(input, sourceRate: 48000)!

    #expect(Int(result.frameLength) == 512)
    let out = result.floatChannelData![0]
    for i in 0..<512 {
      #expect(abs(out[i] - 0.75) < 0.0001)
    }
  }

  @Test("mono 24kHz resamples to 48kHz")
  func monoResample() {
    let input = makeMonoBuffer(sampleRate: 24000, frameCount: 240, value: 0.3)
    let result = AudioRecorder.resampleToMono48k(input, sourceRate: 24000)!

    #expect(result.format.sampleRate == 48000)
    #expect(Int(result.frameLength) == 480)

    let out = result.floatChannelData![0]
    for i in 0..<480 {
      #expect(abs(out[i] - 0.3) < 0.0001, "Frame \(i): expected 0.3, got \(out[i])")
    }
  }

  @Test("resample preserves linear ramp")
  func resamplePreservesRamp() {
    // Create a stereo buffer with a linear ramp on both channels
    let inFrames = 100
    let fmt = AVAudioFormat(
      commonFormat: .pcmFormatFloat32, sampleRate: 24000, channels: 2, interleaved: true)!
    let buf = AVAudioPCMBuffer(pcmFormat: fmt, frameCapacity: AVAudioFrameCount(inFrames))!
    buf.frameLength = AVAudioFrameCount(inFrames)
    let data = buf.floatChannelData![0]
    for i in 0..<inFrames {
      let v = Float(i) / Float(inFrames - 1)  // 0.0 to 1.0
      data[i * 2] = v
      data[i * 2 + 1] = v
    }

    let result = AudioRecorder.resampleToMono48k(buf, sourceRate: 24000)!
    let outFrames = Int(result.frameLength)
    #expect(outFrames == 200)

    let out = result.floatChannelData![0]
    // Output should be a linear ramp from 0.0 to 1.0 (interpolated)
    for i in 0..<outFrames {
      let expected = Float(i) / Float(outFrames - 1)
      #expect(
        abs(out[i] - expected) < 0.02,
        "Frame \(i): expected ~\(expected), got \(out[i])")
    }
  }

  @Test("output frame count is correct for various rate ratios")
  func outputFrameCount() {
    let rates: [(Double, Int, Int)] = [
      (24000, 240, 480),  // 2x upsample
      (16000, 160, 480),  // 3x upsample
      (44100, 441, 481),  // non-integer ratio (ceil rounds up)
      (48000, 480, 480),  // passthrough
    ]
    for (rate, inCount, expectedOut) in rates {
      let input = makeStereoBuffer(sampleRate: rate, frameCount: inCount, left: 0.5, right: 0.5)
      let result = AudioRecorder.resampleToMono48k(input, sourceRate: rate)!
      #expect(
        Int(result.frameLength) == expectedOut,
        "\(rate)Hz: \(inCount) in -> expected \(expectedOut) out, got \(result.frameLength)")
    }
  }
}

